using System; using Jotunn.Managers; using UnityEngine;
namespace SuijinMaterials.Merchants { public sealed class JotunnMerchantStockFacade:IMerchantStockFacade { public object Add(MerchantStockDefinition d,MerchantListingSettings s){GameObject traderPrefab=PrefabManager.Instance.GetPrefab(d.TraderPrefabId)??throw new InvalidOperationException("Missing trader "+d.TraderPrefabId);GameObject itemPrefab=PrefabManager.Instance.GetPrefab(d.MaterialPrefabId)??throw new InvalidOperationException("Missing item "+d.MaterialPrefabId);Trader trader=traderPrefab.GetComponent<Trader>()??throw new InvalidOperationException("Trader component missing on "+d.TraderPrefabId);ItemDrop item=itemPrefab.GetComponent<ItemDrop>()??throw new InvalidOperationException("ItemDrop missing on "+d.MaterialPrefabId);var entry=new Trader.TradeItem{m_prefab=item,m_stack=s.Stack,m_price=s.Price,m_requiredGlobalKey=d.RequiredGlobalKey};trader.m_items.Add(entry);return new Handle(trader,entry);}public void Remove(object h){var x=(Handle)h;x.Trader.m_items.Remove(x.Entry);}private sealed class Handle{public Handle(Trader t,Trader.TradeItem e){Trader=t;Entry=e;}public Trader Trader{get;}public Trader.TradeItem Entry{get;}} } }
